   204→          {/* Weekday Headers */}
   205→          <div className="grid grid-cols-7 mb-2">
   206→            {['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'].map(day => (
   207→              <div key={day} className="text-center text-xs font-medium text-muted-foreground py-2">
   208→                {day}
   209→              </div>
   210→            ))}
   211→          </div>
   212→
   213→          {/* Calendar Grid */}
   214→          <div className="grid grid-cols-7 gap-1">
   215→            {calendarDays.map((day, idx) => {
   216→              if (!day) {
   217→                return <div key={`empty-${idx}`} className="aspect-square" />;
   218→              }
   219→
   220→              const dayKurse = getKurseForDate(day);
   221→              const isToday = isSameDay(day, new Date());
   222→              const isSelected = selectedDate && isSameDay(day, selectedDate);
   223→
   224→              return (
   225→                <button
   226→                  key={day.toISOString()}
   227→                  onClick={() => setSelectedDate(day)}
   228→                  className={`
   229→                    aspect-square rounded-xl p-1 flex flex-col items-center justify-start gap-0.5
   230→                    transition-all hover:bg-accent relative
   231→                    ${isToday ? 'ring-2 ring-primary ring-offset-2 ring-offset-background' : ''}
   232→                    ${isSelected ? 'bg-primary text-primary-foreground' : ''}
   233→                  `}
   234→                >
   235→                  <span className={`text-sm font-medium ${isSelected ? 'text-primary-foreground' : ''}`}>
   236→                    {format(day, 'd')}
   237→                  </span>
   238→                  {dayKurse.length > 0 && (
   239→                    <div className="flex gap-0.5">
   240→                      {dayKurse.slice(0, 3).map((k, i) => (
   241→                        <div
   242→                          key={k.record_id}
   243→                          className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-primary-foreground' : 'bg-primary'}`}
   244→                        />
   245→                      ))}
   246→                      {dayKurse.length > 3 && (
   247→                        <span className={`text-[9px] ${isSelected ? 'text-primary-foreground' : 'text-muted-foreground'}`}>
   248→                          +{dayKurse.length - 3}
   249→                        </span>
   250→                      )}
   251→                    </div>
   252→                  )}
   253→                </button>
   254→              );
   255→            })}
   256→          </div>
   257→        </div>
   258→
   259→        {/* Selected Day Detail */}
   260→        <div className="bg-card rounded-2xl border border-border/50 p-5">
   261→          <div className="flex items-center justify-between mb-4">
   262→            <h3 className="font-semibold text-foreground">
   263→              {selectedDate ? format(selectedDate, 'EEEE, d. MMMM', { locale: de }) : 'Wählen Sie einen Tag'}
   264→            </h3>
   265→            {selectedDate && (
   266→              <Button
   267→                variant="ghost"
   268→                size="icon"
   269→                className="h-8 w-8"
   270→                onClick={() => { setIsCreateDialogOpen(true); }}
   271→              >
   272→                <Plus size={16} />
   273→              </Button>
   274→            )}
   275→          </div>
   276→
   277→          {!selectedDate ? (
   278→            <div className="flex flex-col items-center justify-center py-12 text-center">
   279→              <Calendar size={40} className="text-muted-foreground/30 mb-3" />
   280→              <p className="text-sm text-muted-foreground">Klicken Sie auf einen Tag im Kalender</p>
   281→            </div>
   282→          ) : selectedDateKurse.length === 0 ? (
   283→            <div className="flex flex-col items-center justify-center py-12 text-center">
   284→              <BookOpen size={40} className="text-muted-foreground/30 mb-3" />
   285→              <p className="text-sm text-muted-foreground mb-3">Keine Kurse an diesem Tag</p>
   286→              <Button variant="outline" size="sm" onClick={() => setIsCreateDialogOpen(true)} className="gap-2">
   287→                <Plus size={14} />
   288→                Kurs anlegen
   289→              </Button>
   290→            </div>
   291→          ) : (
   292→            <div className="space-y-3">
   293→              {selectedDateKurse.map(kurs => {
   294→                const kursAnmeldungen = getAnmeldungenForKurs(kurs.record_id);
   295→                const maxTeilnehmer = kurs.fields.max_teilnehmer || 0;
   296→                const fillPercent = maxTeilnehmer > 0 ? Math.min(100, (kursAnmeldungen.length / maxTeilnehmer) * 100) : 0;
   297→
   298→                return (
   299→                  <div
   300→                    key={kurs.record_id}
   301→                    className="p-4 rounded-xl bg-accent/50 border border-border/50 cursor-pointer hover:border-primary/30 transition-colors"
   302→                    onClick={() => { setSelectedKurs(kurs); setIsEditDialogOpen(true); }}
   303→                  >
   304→                    <div className="flex items-start justify-between gap-2 mb-2">
   305→                      <h4 className="font-medium text-foreground line-clamp-1">{kurs.fields.titel || 'Ohne Titel'}</h4>
   306→                      <Badge variant="secondary" className="shrink-0 text-xs">
   307→                        {formatCurrency(kurs.fields.preis)}
   308→                      </Badge>
   309→                    </div>
   310→
   311→                    <div className="space-y-1.5 text-xs text-muted-foreground">
   312→                      {kurs.dozentName && (
   313→                        <div className="flex items-center gap-1.5">
   314→                          <GraduationCap size={12} />
   315→                          <span>{kurs.dozentName}</span>
   316→                        </div>
   317→                      )}
   318→                      {kurs.raumName && (
   319→                        <div className="flex items-center gap-1.5">
   320→                          <MapPin size={12} />
   321→                          <span>{kurs.raumName}</span>
   322→                        </div>
   323→                      )}
   324→                      <div className="flex items-center gap-1.5">
   325→                        <Users size={12} />
   326→                        <span>{kursAnmeldungen.length} / {maxTeilnehmer || '∞'} Teilnehmer</span>
   327→                      </div>
   328→                    </div>
   329→
   330→                    {maxTeilnehmer > 0 && (
   331→                      <div className="mt-3">
   332→                        <div className="h-1.5 bg-muted rounded-full overflow-hidden">
   333→                          <div
   334→                            className={`h-full rounded-full transition-all ${fillPercent >= 100 ? 'bg-rose-500' : fillPercent >= 75 ? 'bg-amber-500' : 'bg-emerald-500'}`}
   335→                            style={{ width: `${fillPercent}%` }}
   336→                          />
   337→                        </div>
   338→                      </div>
   339→                    )}
   340→                  </div>
   341→                );
   342→              })}
   343→            </div>
   344→          )}
   345→        </div>
   346→      </div>
   347→
   348→      {/* Upcoming Courses List */}
   349→      <div className="bg-card rounded-2xl border border-border/50 p-5">
   350→        <h3 className="font-semibold text-foreground mb-4">Kommende Kurse</h3>
   351→        {enrichedKurse.filter(k => k.fields.startdatum && new Date(k.fields.startdatum) >= new Date()).length === 0 ? (
   352→          <p className="text-sm text-muted-foreground text-center py-8">Keine kommenden Kurse</p>
   353→        ) : (
   354→          <div className="overflow-x-auto">
   355→            <table className="w-full">
   356→              <thead>
   357→                <tr className="border-b border-border">
   358→                  <th className="text-left text-xs font-medium text-muted-foreground py-2 pr-4">Kurs</th>
   359→                  <th className="text-left text-xs font-medium text-muted-foreground py-2 pr-4 hidden sm:table-cell">Dozent</th>
   360→                  <th className="text-left text-xs font-medium text-muted-foreground py-2 pr-4">Zeitraum</th>
   361→                  <th className="text-left text-xs font-medium text-muted-foreground py-2 pr-4 hidden md:table-cell">Raum</th>
   362→                  <th className="text-right text-xs font-medium text-muted-foreground py-2">Teilnehmer</th>
   363→                </tr>
   364→              </thead>
   365→              <tbody>
   366→                {enrichedKurse
   367→                  .filter(k => k.fields.startdatum && new Date(k.fields.startdatum) >= new Date())
   368→                  .sort((a, b) => new Date(a.fields.startdatum!).getTime() - new Date(b.fields.startdatum!).getTime())
   369→                  .slice(0, 10)
   370→                  .map(kurs => {
   371→                    const kursAnmeldungen = getAnmeldungenForKurs(kurs.record_id);
   372→                    return (
   373→                      <tr
   374→                        key={kurs.record_id}
   375→                        className="border-b border-border/50 last:border-0 hover:bg-accent/50 cursor-pointer transition-colors"
   376→                        onClick={() => { setSelectedKurs(kurs); setIsEditDialogOpen(true); }}
   377→                      >
   378→                        <td className="py-3 pr-4">
   379→                          <p className="font-medium text-foreground text-sm">{kurs.fields.titel}</p>
   380→                        </td>
   381→                        <td className="py-3 pr-4 hidden sm:table-cell">
   382→                          <p className="text-sm text-muted-foreground">{kurs.dozentName || '—'}</p>
   383→                        </td>
   384→                        <td className="py-3 pr-4">
   385→                          <p className="text-sm text-muted-foreground">
   386→                            {formatDate(kurs.fields.startdatum)}
   387→                            {kurs.fields.enddatum && kurs.fields.enddatum !== kurs.fields.startdatum && (
   388→                              <> – {formatDate(kurs.fields.enddatum)}</>
   389→                            )}
   390→                          </p>
   391→                        </td>
   392→                        <td className="py-3 pr-4 hidden md:table-cell">
   393→                          <p className="text-sm text-muted-foreground">{kurs.raumName || '—'}</p>
   394→                        </td>
   395→                        <td className="py-3 text-right">
   396→                          <Badge variant={kursAnmeldungen.length >= (kurs.fields.max_teilnehmer || 999) ? 'destructive' : 'secondary'}>
   397→                            {kursAnmeldungen.length} / {kurs.fields.max_teilnehmer || '∞'}
   398→                          </Badge>
   399→                        </td>
   400→                      </tr>
   401→                    );
   402→                  })}
   403→              </tbody>
   404→            </table>
   405→          </div>
   406→        )}
   407→      </div>
   408→
   409→      {/* Create Dialog */}
   410→      <KursDialog
   411→        open={isCreateDialogOpen}
   412→        onOpenChange={setIsCreateDialogOpen}
   413→        onSave={handleCreateKurs}
   414→        defaultDate={selectedDate}
   415→        dozenten={dozenten}
   416→        raeume={raeume}
   417→      />
   418→
   419→      {/* Edit Dialog */}
   420→      {selectedKurs && (
   421→        <KursDialog
   422→          open={isEditDialogOpen}
   423→          onOpenChange={(open) => { setIsEditDialogOpen(open); if (!open) setSelectedKurs(null); }}
   424→          onSave={(data) => handleUpdateKurs(selectedKurs.record_id, data)}
   425→          onDelete={() => setIsDeleteConfirmOpen(true)}
   426→          kurs={selectedKurs}
   427→          dozenten={dozenten}
   428→          raeume={raeume}
   429→          anmeldungen={getAnmeldungenForKurs(selectedKurs.record_id)}
   430→        />
   431→      )}
   432→
   433→      {/* Delete Confirm Dialog */}
   434→      <Dialog open={isDeleteConfirmOpen} onOpenChange={setIsDeleteConfirmOpen}>
   435→        <DialogContent className="max-w-sm">
   436→          <DialogHeader>
   437→            <DialogTitle>Kurs löschen?</DialogTitle>
   438→          </DialogHeader>
   439→          <p className="text-sm text-muted-foreground">
   440→            Möchten Sie den Kurs "{selectedKurs?.fields.titel}" wirklich löschen? Diese Aktion kann nicht rückgängig gemacht werden.
   441→          </p>
   442→          <div className="flex justify-end gap-2 mt-4">
   443→            <Button variant="outline" onClick={() => setIsDeleteConfirmOpen(false)}>Abbrechen</Button>
   444→            <Button variant="destructive" onClick={() => selectedKurs && handleDeleteKurs(selectedKurs.record_id)}>
   445→              Löschen
   446→            </Button>
   447→          </div>
   448→        </DialogContent>
   449→      </Dialog>
   450→    </div>
   451→  );
   452→}
   453→
   454→interface KursDialogProps {
   455→  open: boolean;
   456→  onOpenChange: (open: boolean) => void;
   457→  onSave: (data: Kurse['fields']) => void;
   458→  onDelete?: () => void;
   459→  kurs?: EnrichedKurse;
   460→  defaultDate?: Date | null;
   461→  dozenten: Array<{ record_id: string; fields: { vorname?: string; nachname?: string } }>;
   462→  raeume: Array<{ record_id: string; fields: { raumname?: string; gebaeude?: string } }>;
   463→  anmeldungen?: EnrichedAnmeldungen[];
   464→}
   465→
   466→function KursDialog({ open, onOpenChange, onSave, onDelete, kurs, defaultDate, dozenten, raeume, anmeldungen }: KursDialogProps) {
   467→  const [formData, setFormData] = useState<Kurse['fields']>({});
   468→  const [saving, setSaving] = useState(false);
   469→
   470→  useState(() => {
   471→    if (kurs) {
   472→      setFormData({
   473→        titel: kurs.fields.titel || '',
   474→        beschreibung: kurs.fields.beschreibung || '',
   475→        startdatum: kurs.fields.startdatum || '',
   476→        enddatum: kurs.fields.enddatum || '',
   477→        max_teilnehmer: kurs.fields.max_teilnehmer,
   478→        preis: kurs.fields.preis,
   479→        dozent: kurs.fields.dozent,
   480→        raum: kurs.fields.raum,
   481→      });
   482→    } else if (defaultDate) {
   483→      setFormData({
   484→        startdatum: format(defaultDate, 'yyyy-MM-dd'),
   485→        enddatum: format(defaultDate, 'yyyy-MM-dd'),
   486→      });
   487→    } else {
   488→      setFormData({});
   489→    }
   490→  });
   491→
   492→  const handleSubmit = async (e: React.FormEvent) => {
   493→    e.preventDefault();
   494→    setSaving(true);
   495→    try {
   496→      await onSave(formData);
   497→    } finally {
   498→      setSaving(false);
   499→    }
   500→  };
   501→
   502→  const dozentId = kurs?.fields.dozent ? extractRecordId(kurs.fields.dozent) : undefined;
   503→  const raumId = kurs?.fields.raum ? extractRecordId(kurs.fields.raum) : undefined;
   504→
   505→  return (
   506→    <Dialog open={open} onOpenChange={onOpenChange}>
   507→      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
   508→        <DialogHeader>
   509→          <DialogTitle>{kurs ? 'Kurs bearbeiten' : 'Neuer Kurs'}</DialogTitle>
   510→        </DialogHeader>
   511→
   512→        <form onSubmit={handleSubmit} className="space-y-4">
   513→          <div>
   514→            <Label htmlFor="titel">Kurstitel</Label>
   515→            <Input
   516→              id="titel"
   517→              value={formData.titel || ''}
   518→              onChange={(e) => setFormData({ ...formData, titel: e.target.value })}
   519→              placeholder="z.B. Yoga für Anfänger"
   520→            />
   521→          </div>
   522→
   523→          <div>
   524→            <Label htmlFor="beschreibung">Beschreibung</Label>
   525→            <Textarea
   526→              id="beschreibung"
   527→              value={formData.beschreibung || ''}
   528→              onChange={(e) => setFormData({ ...formData, beschreibung: e.target.value })}
   529→              placeholder="Kursbeschreibung..."
   530→              rows={3}
   531→            />
   532→          </div>
   533→
   534→          <div className="grid grid-cols-2 gap-4">
   535→            <div>
   536→              <Label htmlFor="startdatum">Startdatum</Label>
   537→              <Input
   538→                id="startdatum"
   539→                type="date"
   540→                value={formData.startdatum || ''}
   541→                onChange={(e) => setFormData({ ...formData, startdatum: e.target.value })}
   542→              />
   543→            </div>
   544→            <div>
   545→              <Label htmlFor="enddatum">Enddatum</Label>
   546→              <Input
   547→                id="enddatum"
   548→                type="date"
   549→                value={formData.enddatum || ''}
   550→                onChange={(e) => setFormData({ ...formData, enddatum: e.target.value })}
   551→              />
   552→            </div>
   553→          </div>
   554→
   555→          <div className="grid grid-cols-2 gap-4">
   556→            <div>
   557→              <Label htmlFor="max_teilnehmer">Max. Teilnehmer</Label>
   558→              <Input
   559→                id="max_teilnehmer"
   560→                type="number"
   561→                min={0}
   562→                value={formData.max_teilnehmer ?? ''}
   563→                onChange={(e) => setFormData({ ...formData, max_teilnehmer: e.target.value ? Number(e.target.value) : undefined })}
   564→                placeholder="Unbegrenzt"
   565→              />
   566→            </div>
   567→            <div>
   568→              <Label htmlFor="preis">Preis (EUR)</Label>
   569→              <Input
   570→                id="preis"
   571→                type="number"
   572→                min={0}
   573→                step="0.01"
   574→                value={formData.preis ?? ''}
   575→                onChange={(e) => setFormData({ ...formData, preis: e.target.value ? Number(e.target.value) : undefined })}
   576→                placeholder="0,00"
   577→              />
   578→            </div>
   579→          </div>
   580→
   581→          <div>
   582→            <Label htmlFor="dozent">Dozent</Label>
   583→            <Select
   584→              value={formData.dozent ? extractRecordId(formData.dozent) || 'none' : dozentId || 'none'}
   585→              onValueChange={(val) => setFormData({
   586→                ...formData,
   587→                dozent: val === 'none' ? undefined : createRecordUrl(APP_IDS.DOZENTEN, val)
   588→              })}
   589→            >
   590→              <SelectTrigger>
   591→                <SelectValue placeholder="Dozent auswählen" />
   592→              </SelectTrigger>
   593→              <SelectContent>
   594→                <SelectItem value="none">Kein Dozent</SelectItem>
   595→                {dozenten.map(d => (
   596→                  <SelectItem key={d.record_id} value={d.record_id}>
   597→                    {d.fields.vorname} {d.fields.nachname}
   598→                  </SelectItem>
   599→                ))}
   600→              </SelectContent>
   601→            </Select>
   602→          </div>
   603→
   604→          <div>
   605→            <Label htmlFor="raum">Raum</Label>
   606→            <Select
   607→              value={formData.raum ? extractRecordId(formData.raum) || 'none' : raumId || 'none'}
   608→              onValueChange={(val) => setFormData({
   609→                ...formData,
   610→                raum: val === 'none' ? undefined : createRecordUrl(APP_IDS.RAEUME, val)
   611→              })}
   612→            >
   613→              <SelectTrigger>
   614→                <SelectValue placeholder="Raum auswählen" />
   615→              </SelectTrigger>
   616→              <SelectContent>
   617→                <SelectItem value="none">Kein Raum</SelectItem>
   618→                {raeume.map(r => (
   619→                  <SelectItem key={r.record_id} value={r.record_id}>
   620→                    {r.fields.raumname} {r.fields.gebaeude && `(${r.fields.gebaeude})`}
   621→                  </SelectItem>
   622→                ))}
   623→              </SelectContent>
   624→            </Select>
   625→          </div>
   626→
   627→          {/* Show registrations if editing */}
   628→          {kurs && anmeldungen && anmeldungen.length > 0 && (
   629→            <div className="border-t border-border pt-4">
   630→              <Label className="mb-2 block">Anmeldungen ({anmeldungen.length})</Label>
   631→              <div className="max-h-32 overflow-y-auto space-y-1">
   632→                {anmeldungen.map(a => (
   633→                  <div key={a.record_id} className="flex items-center justify-between py-1.5 px-2 rounded bg-accent/50 text-sm">
   634→                    <span>{a.teilnehmerName || 'Unbekannt'}</span>
   635→                    <Badge variant={a.fields.bezahlt ? 'default' : 'secondary'} className="text-xs">
   636→                      {a.fields.bezahlt ? <Check size={10} className="mr-1" /> : null}
   637→                      {a.fields.bezahlt ? 'Bezahlt' : 'Offen'}
   638→                    </Badge>
   639→                  </div>
   640→                ))}
   641→              </div>
   642→            </div>
   643→          )}
   644→
   645→          <div className="flex justify-between pt-4">
   646→            {onDelete ? (
   647→              <Button type="button" variant="ghost" className="text-destructive hover:text-destructive" onClick={onDelete}>
   648→                <Trash2 size={16} className="mr-2" />
   649→                Löschen
   650→              </Button>
   651→            ) : (
   652→              <div />
   653→            )}
   654→            <div className="flex gap-2">
   655→              <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
   656→                Abbrechen
   657→              </Button>
   658→              <Button type="submit" disabled={saving}>
   659→                {saving ? 'Speichern...' : 'Speichern'}
   660→              </Button>
   661→            </div>
   662→          </div>
   663→        </form>
   664→      </DialogContent>
   665→    </Dialog>
   666→  );
   667→}
   668→
   669→function DashboardSkeleton() {
   670→  return (
   671→    <div className="space-y-6">
   672→      <div className="flex items-center justify-between">
   673→        <Skeleton className="h-8 w-48" />
   674→        <Skeleton className="h-9 w-36" />
   675→      </div>
   676→      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   677→        {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-24 rounded-2xl" />)}
   678→      </div>
   679→      <Skeleton className="h-64 rounded-2xl" />
   680→    </div>
   681→  );
   682→}
   683→
   684→function DashboardError({ error, onRetry }: { error: Error; onRetry: () => void }) {
   685→  return (
   686→    <div className="flex flex-col items-center justify-center py-24 gap-4">
   687→      <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   688→        <AlertCircle size={22} className="text-destructive" />
   689→      </div>
   690→      <div className="text-center">
   691→        <h3 className="font-semibold text-foreground mb-1">Fehler beim Laden</h3>
   692→        <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
   693→      </div>
   694→      <Button variant="outline" size="sm" onClick={onRetry}>Erneut versuchen</Button>
   695→    </div>
   696→  );
   697→}
